    private void refreshKeys(){if(keyDisplay!=null)keyDisplay.setText(originalNote<0?"—":MusicalKey.FLATS[originalNote]);if(targetKeyButton!=null)targetKeyButton.setText((targetNote<0?"—":MusicalKey.FLATS[targetNote])+" ▾");}
    private void configureSongKeys(String filename){var prefs=getSharedPreferences("mix",MODE_PRIVATE);int from=-1,to=-1;if(setlist!=null&&setlistIndex>=0){SetlistSpec.Song song=setlist.songs.get(setlistIndex);from=MusicalKey.parse(song.originalKey);to=MusicalKey.parse(song.tonalKey);}if(from<0)from=MusicalKey.parse(activeProject.originalKey);if(from<0)from=MusicalKey.filename(filename);if(from<0)from=MusicalKey.filename(activeProject.title);originalNote=prefs.getInt("originalNote:"+projectKey,from);int savedTarget=MusicalKey.parse(activeProject.targetKey);if(to<0)to=savedTarget<0?originalNote:savedTarget;targetNote=prefs.getInt("targetNote:"+projectKey,to);for(int i=0;i<mixer.trackCount();i++)mixer.setPitchEnabled(i,prefs.getBoolean("pitchTrack:"+projectKey+":"+i,mixer.pitchEnabled(i)));for(int kind=-1;kind>=-5;kind--){mixer.setChannelPan(kind,prefs.getFloat("pan:"+projectKey+":"+kind,0));if(prefs.contains("mute:"+projectKey+":"+kind))mixer.setMuted(kind,prefs.getBoolean("mute:"+projectKey+":"+kind,false));mixer.setSolo(kind,prefs.getBoolean("solo:"+projectKey+":"+kind,false));}mixer.setVsLevel(prefs.getFloat("vsLevel:"+projectKey,1));mixer.setGuideLevel(prefs.getFloat("guideLevel:"+projectKey,1));mixer.useProjectClick(!prefs.getBoolean("nativeClick",!prefs.getBoolean("projectClick:"+projectKey,mixer.audibleProjectClick())));for(int i=0;i<mixer.trackCount();i++)mixer.setTrackRoute(i,prefs.getInt("trackRoute:"+projectKey+":"+i,-1));if(originalNote>=0&&targetNote>=0){mixer.setTranspose(MusicalKey.delta(originalNote,targetNote));mixer.setPadNote(prefs.getInt("padNote:"+projectKey,targetNote));}refreshKeys();}
    private void chooseNote(Button anchor,boolean padNote){if(!padNote&&originalNote<0){new android.app.AlertDialog.Builder(this).setMessage(R.string.original_required).setPositiveButton(R.string.original_key,(d,w)->informOriginalKey()).setNegativeButton(android.R.string.cancel,null).show();return;}PopupMenu menu=new PopupMenu(this,anchor);for(int i=0;i<12;i++){final int note=i;menu.getMenu().add(0,i,i,MusicalKey.FLATS[i]).setCheckable(true).setChecked((padNote?mixer.getPadNote():targetNote)==i);}menu.getMenu().setGroupCheckable(0,true,true);menu.setOnMenuItemClickListener(item->{int note=item.getItemId();if(padNote){mixer.setPadNote(note);getSharedPreferences("mix",MODE_PRIVATE).edit().putInt(activeProject==null?"padNote":"padNote:"+projectKey,note).apply();}else{targetNote=note;mixer.setTranspose(MusicalKey.delta(originalNote,note));mixer.setPadNote(note);getSharedPreferences("mix",MODE_PRIVATE).edit().putInt("targetNote:"+projectKey,note).putInt("padNote:"+projectKey,note).apply();refreshKeys();renderSetlist();}return true;});menu.show();}
    private void informOriginalKey(){if(activeProject==null){Toast.makeText(this,R.string.project_required,Toast.LENGTH_SHORT).show();return;}new android.app.AlertDialog.Builder(this).setTitle(R.string.original_key).setSingleChoiceItems(MusicalKey.FLATS,originalNote,(d,note)->{originalNote=note;if(targetNote<0)targetNote=note;getSharedPreferences("mix",MODE_PRIVATE).edit().putInt("originalNote:"+projectKey,note).putInt("targetNote:"+projectKey,targetNote).apply();mixer.setTranspose(MusicalKey.delta(originalNote,targetNote));mixer.setPadNote(targetNote);refreshKeys();d.dismiss();}).setNegativeButton(android.R.string.cancel,null).show();}
    private void chooseSound(int request){if(loading)return;Intent picker=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("audio/*");picker.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,request==IMPORT_PADS);picker.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/wav","audio/x-wav","audio/mpeg"});picker.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivityForResult(picker,request);}catch(android.content.ActivityNotFoundException unavailable){status.setText(R.string.no_picker);}}
    void importSoundFiles(int request,List<Uri> files){if(files.isEmpty()||loading)return;loading=true;lastImportError=0;status.setText(R.string.importing_sounds);imports.execute(()->{try{if(request==IMPORT_PADS)soundLibrary.importPads(files,(done,total)->runOnUiThread(()->{if(!destroyed)status.setText(getString(R.string.loading_count,done,total));}));else{if(files.size()!=1)throw new java.io.IOException("click-count");soundLibrary.importClick(files.get(0),request==IMPORT_ACCENT);}runOnUiThread(()->{if(destroyed)return;loading=false;status.setText(R.string.sounds_imported);if(settingsDialog!=null&&settingsDialog.isShowing())showSettings(2);renderMixer();});}catch(Exception|OutOfMemoryError failure){String message=failure.getMessage();int error="pad-count".equals(message)||"pad-names".equals(message)?R.string.pad_names_error:"pad-duration".equals(message)?R.string.pad_duration_error:"click-duration".equals(message)?R.string.click_duration_error:R.string.sound_import_failed;importFailure(error);}});}
    private void showPitchSelection(){List<Integer> tracks=new ArrayList<>();for(int i=0;i<mixer.trackCount();i++)if(mixer.role(i)!=2)tracks.add(i);String[] names=new String[tracks.size()];boolean[] enabled=new boolean[names.length];for(int j=0;j<names.length;j++){int i=tracks.get(j);names[j]=mixer.hasImported()?mixer.trackName(i):getString(new int[]{R.string.bass,R.string.keys,R.string.drums}[i]);enabled[j]=mixer.pitchEnabled(i);}new android.app.AlertDialog.Builder(this).setTitle(R.string.pitch_tracks).setMultiChoiceItems(names,enabled,(d,index,on)->{int i=tracks.get(index);mixer.setPitchEnabled(i,on);getSharedPreferences("mix",MODE_PRIVATE).edit().putBoolean("pitchTrack:"+projectKey+":"+i,mixer.pitchEnabled(i)).apply();renderMixer();}).setPositiveButton(android.R.string.ok,null).show();}

    private void togglePlay(){if(setlist!=null&&setlistIndex<0)return;if(mixer.isPlaying())mixer.pause();else if(ready()){if(mixer.hasPads())mixer.setPad(true);mixer.play();}}
    private void togglePad(){if(!mixer.hasPads()&&!isolatedTest()){showSettings(2);Toast.makeText(this,R.string.pad_import_help,Toast.LENGTH_LONG).show();return;}if(mixer.isPad())mixer.setPad(false);else if(ready())mixer.setPad(true);}
    private void toggleClick(){if(mixer.isClick())mixer.setClick(false);else if(ready())mixer.setClick(true);}
    private void applyBpm(){try{setBpm(Integer.parseInt(bpmField.getText().toString()));}catch(NumberFormatException ignored){}bpmField.setText(String.valueOf(mixer.getBpm()));}
    private void changeBpm(int delta){setBpm(mixer.getBpm()+delta);bpmField.setText(String.valueOf(mixer.getBpm()));}
    private void tapTempo(){long now=SystemClock.elapsedRealtime();if(now-lastTap>2000)taps.clear();lastTap=now;taps.add(now);while(taps.size()>6)taps.remove();if(taps.size()>1&&now>taps.peekFirst()){setBpm((int)Math.round(60000.0*(taps.size()-1)/(now-taps.peekFirst())));bpmField.setText(String.valueOf(mixer.getBpm()));}}
