    private void openProjectFolder(Uri tree,String selected,boolean persistent){
        if(loading)return;loading=true;lastImportError=0;importButton.setEnabled(false);projectButton.setEnabled(false);setlistButton.setEnabled(false);status.setText(R.string.scanning_project);
        imports.execute(()->{try{ProjectFolder folder=ProjectFolder.scan(getApplicationContext(),tree);List<String> choices=folder.projects();runOnUiThread(()->{if(destroyed)return;if(selected!=null&&choices.contains(selected)){loadProject(folder,selected,persistent);return;}loading=false;setlistButton.setEnabled(true);importButton.setEnabled(true);projectButton.setEnabled(true);if(choices.isEmpty()){importFailure(R.string.no_projects);return;}new android.app.AlertDialog.Builder(this).setTitle(R.string.choose_project).setItems(choices.toArray(new String[0]),(dialog,index)->{loading=true;loadProject(folder,choices.get(index),persistent);}).setNegativeButton(android.R.string.cancel,null).show();});}catch(Exception failure){importFailure(R.string.project_failed);}});
    }
    void loadProject(ProjectFolder folder,String filename,boolean persistent){
        loading=true;lastImportError=0;if(projectNotice!=null)projectNotice.dismiss();importButton.setEnabled(false);projectButton.setEnabled(false);boolean keepPad=getSharedPreferences("mix",MODE_PRIVATE).getBoolean("keepPad",false)&&mixer.isPad();mixer.prepareProjectChange(keepPad);if(!keepPad&&audio!=null){audio.close();audio=null;}status.setText(R.string.loading_audio);
        imports.execute(()->{try{ProjectLoader.Result result=ProjectLoader.read(getApplicationContext(),folder,filename,(done,total)->runOnUiThread(()->{if(!destroyed)status.setText(getString(R.string.loading_count,done,total));}));runOnUiThread(()->{if(destroyed){result.close();return;}projectFolder=folder;projectFilename=filename;activeProject=result.spec;projectKey=folder.tree+":"+filename;currentUris=new ArrayList<>();sourcePeaks=result.peaks;PcmTrack[] pitchSources=Arrays.copyOf(result.tracks,result.tracks.length+(result.guidePreview==null?0:1));if(result.guidePreview!=null)pitchSources[result.tracks.length]=result.guidePreview;PitchBank pitches=new PitchBank(pitchSources,mixer);mixer.load(Arrays.copyOf(pitches.tracks,result.tracks.length));mixer.configureProject(activeProject);mixer.configureGuidePreview(result.guidePreview==null?null:pitches.tracks[result.tracks.length],result.guideIndex);var prefs=getSharedPreferences("mix",MODE_PRIVATE);for(int i=0;i<mixer.trackCount();i++){mixer.setGain(i,prefs.getFloat(gainKey(i),(float)activeProject.tracks.get(i).volume));mixer.setPan(i,prefs.getFloat("pan:"+projectKey+":"+i,(float)activeProject.tracks.get(i).pan));mixer.setMuted(i,prefs.getBoolean("mute:"+projectKey+":"+i,activeProject.tracks.get(i).mute));mixer.setSolo(i,prefs.getBoolean("solo:"+projectKey+":"+i,activeProject.tracks.get(i).solo));}mixer.setBpm(prefs.getInt("projectBpm:"+projectKey,mixer.getBpm()));bpmField.setText(String.valueOf(mixer.getBpm()));songHeading(activeProject.title);if(persistent)prefs.edit().putString("sourceMode","project").putString("projectTree",folder.tree.toString()).putString("projectFile",filename).apply();renderMixer();loading=false;importButton.setEnabled(true);projectButton.setEnabled(true);status.setText(R.string.project_ready);projectOpened(folder,filename,persistent);configureSongKeys(filename);renderSetlist();renderMixer();waveform.resetViewport();waveform.invalidate();if(!activeProject.warnings.isEmpty())showCompatibility(false);});}catch(ProjectSpec.Processing unsupported){importFailure(R.string.project_processing);}catch(ProjectFolder.Missing missing){importFailure(R.string.project_missing);}catch(ProjectSpec.Invalid invalid){importFailure(R.string.project_invalid_data);}catch(WavImport.NotSeekable unsupported){importFailure(R.string.not_seekable);}catch(WavReader.Unsupported unsupported){importFailure(R.string.unsupported_wav);}catch(Mp3Decode.NoSpace storage){importFailure(R.string.audio_cache_full);}catch(OutOfMemoryError memory){importFailure(R.string.import_memory);}catch(Exception failure){importFailure(R.string.project_failed);}});
    }

    private void chooseWav(){
        Intent picker=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("audio/*");
        picker.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);picker.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/wav","audio/x-wav","audio/wave","audio/vnd.wave","audio/mpeg"});
        picker.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);
        try{startActivityForResult(picker,OPEN_WAV);}catch(android.content.ActivityNotFoundException unavailable){status.setText(R.string.no_picker);}
    }
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);
        if(result!=RESULT_OK||data==null)return;if(request==SCAN_REMOTE){String invitation=data.getStringExtra("invitation");try{com.onebytelabs.zlplay.remote.QrInvitation.parse(invitation);}catch(Exception e){Toast.makeText(this,R.string.remote_bad_qr,Toast.LENGTH_LONG).show();return;}mixer.silence();if(audio!=null){audio.close();audio=null;}if(settingsDialog!=null)settingsDialog.dismiss();startActivity(new Intent(this,RemoteActivity.class).putExtra("invitation",invitation));return;}if(request==IMPORT_COVER&&data.getData()!=null&&coverRequestKey!=null){final String key=coverRequestKey;Uri uri=data.getData();imports.execute(()->{try{Bitmap image=library.importCover(key,uri);runOnUiThread(()->{if(destroyed)return;coverCache.put(key,image);renderSetlist();if(repertoireDialog!=null&&repertoireDialog.isShowing())showRepertoire();});}catch(Exception|OutOfMemoryError error){runOnUiThread(()->Toast.makeText(this,R.string.cover_failed,Toast.LENGTH_LONG).show());}});return;}if(request==IMPORT_PADS||request==IMPORT_NORMAL||request==IMPORT_ACCENT){List<Uri> sounds=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)sounds.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)sounds.add(data.getData());importSoundFiles(request,sounds);return;}
        if(request==OPEN_SETLIST&&data.getData()!=null){Uri tree=data.getData();boolean durable=true;try{getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException unavailable){durable=false;}openSetlistFolder(tree,null,durable,0);return;}
        if(request==OPEN_PROJECT&&data.getData()!=null){Uri tree=data.getData();boolean durable=true;try{getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException unavailable){durable=false;}openProjectFolder(tree,null,durable);return;}
        if(request!=OPEN_WAV)return;
        LinkedHashSet<Uri> selected=new LinkedHashSet<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)selected.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)selected.add(data.getData());
        importAudioUris(new ArrayList<>(selected));
    }
    void importAudioUris(List<Uri> selected){
        if(loading||selected.isEmpty())return;if(selected.size()>32){status.setText(R.string.too_many_files);return;}
        lastImportError=0;loading=true;if(projectNotice!=null)projectNotice.dismiss();importButton.setEnabled(false);projectButton.setEnabled(false);mixer.silence();if(audio!=null){audio.close();audio=null;}status.setText(R.string.loading_audio);
        final List<Uri> files=new ArrayList<>(selected);
        imports.execute(()->{
            try{
                boolean durable=true;for(Uri uri:files)try{if(!"content".equals(uri.getScheme())){durable=false;continue;}getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException unavailable){durable=false;}
                final boolean persistent=durable;
                WavImport.Result decoded=WavImport.read(getApplicationContext(),files,(done,total)->runOnUiThread(()->{if(!destroyed)status.setText(getString(R.string.loading_count,done,total));}));
                runOnUiThread(()->{if(destroyed){decoded.close();return;}activeProject=null;projectKey=null;originalNote=targetNote=-1;refreshKeys();setlist=null;setlistIndex=-1;pendingSong=-1;renderSetlist();currentUris=files;sourcePeaks=decoded.peaks;mixer.load(decoded.tracks);
                    var prefs=getSharedPreferences("mix",MODE_PRIVATE);for(int i=0;i<mixer.trackCount();i++)mixer.setGain(i,prefs.getFloat(gainKey(i),.7f));
                    if(persistent){JSONArray list=new JSONArray();for(Uri uri:files)list.put(uri.toString());prefs.edit().putString("wavSources",list.toString()).putString("sourceMode","wav").apply();}
                    songHeading(getString(R.string.imported_project,mixer.trackCount()));renderMixer();loading=false;importButton.setEnabled(true);projectButton.setEnabled(true);setlistButton.setEnabled(true);status.setText(persistent?R.string.import_done:R.string.import_session_only);waveform.invalidate();if(decoded.temporary)projectNotice=new android.app.AlertDialog.Builder(this).setMessage(R.string.mp3_cache_notice).setPositiveButton(android.R.string.ok,null).show();
                });
            }catch(OutOfMemoryError memory){importFailure(R.string.import_memory);}catch(WavImport.NotSeekable unavailable){importFailure(R.string.not_seekable);}catch(WavReader.TooLarge large){importFailure(R.string.import_memory);}catch(WavReader.Unsupported unsupported){importFailure(R.string.unsupported_wav);}catch(Exception failure){importFailure(R.string.import_failed);}
        });
    }
    private void importFailure(int text){runOnUiThread(()->{if(!destroyed){loading=false;lastImportError=text;pendingSong=-1;setlistButton.setEnabled(true);renderSetlist();importButton.setEnabled(true);projectButton.setEnabled(true);status.setText(text);if(!isFinishing()){if(importErrorDialog!=null)importErrorDialog.dismiss();importErrorDialog=new android.app.AlertDialog.Builder(this).setTitle(text==R.string.no_setlist||text==R.string.setlist_failed?R.string.setlist_error_title:text==R.string.setlist_song_missing||text==R.string.setlist_pitch?R.string.setlist_song_unavailable:R.string.import_error_title).setMessage(text).setPositiveButton(android.R.string.ok,null).show();}}});}
    private void restoreImport(){var prefs=getSharedPreferences("mix",MODE_PRIVATE);if(prefs.getString("sourceMode","").equals("setlist")){openSetlistFolder(Uri.parse(prefs.getString("setlistTree","")),prefs.getString("setlistFile",""),true,prefs.getInt("setlistIndex",0));return;}if(prefs.getString("sourceMode","").equals("project")){openProjectFolder(Uri.parse(prefs.getString("projectTree","")),prefs.getString("projectFile",""),true);return;}try{JSONArray saved=new JSONArray(getSharedPreferences("mix",MODE_PRIVATE).getString("wavSources","[]"));List<Uri> files=new ArrayList<>();for(int i=0;i<saved.length();i++)files.add(Uri.parse(saved.getString(i)));if(!files.isEmpty())importAudioUris(files);}catch(Exception ignored){status.setText(R.string.import_failed);}}
    @Override protected void onDestroy(){destroyed=true;imports.shutdownNow();if(importErrorDialog!=null)importErrorDialog.dismiss();if(projectNotice!=null)projectNotice.dismiss();if(mixerDialog!=null)mixerDialog.dismiss();if(settingsDialog!=null)settingsDialog.dismiss();if(repertoireDialog!=null)repertoireDialog.dismiss();if(quickDialog!=null)quickDialog.dismiss();if(aboutDialog!=null)aboutDialog.dismiss();if(licenseDialog!=null)licenseDialog.dismiss();mixer.closeImported();PcmTrack[] retired=mixer.replacePads(null);if(retired!=null)for(PcmTrack t:retired)t.close();super.onDestroy();}

